  ('fp-g00555', 'forest-production', 'forest-management', 'Medium', 'mock',
   'What does the concept of ''adaptive management'' in forest management emphasize?',
   '[{"id":"a","text":"Adjusting management strategies based on monitoring results"},{"id":"b","text":"Implementing fixed strategies regardless of outcome"},{"id":"c","text":"Maximizing timber production at all costs"},{"id":"d","text":"Completely prohibiting human intervention in forests"}]'::jsonb, 'a'),
  ('fp-g00556', 'forest-production', 'forest-management', 'Medium', 'mock',
