  ('fp-g00602', 'forest-production', 'forest-economics-finance', 'Easy', 'mock',
   'Which of the following is a primary goal of forest economics?',
   '[{"id":"a","text":"To increase the biodiversity index of forest ecosystems."},{"id":"b","text":"To enhance soil fertility in plantation areas."},{"id":"c","text":"To efficiently allocate resources for sustainable forest management."},{"id":"d","text":"To maximize timber yield irrespective of ecological impact."}]'::jsonb, 'c'),
  ('fp-g00603', 'forest-production', 'forest-economics-finance', 'Easy', 'mock',
   'What is the primary focus of forest economics?',
   '[{"id":"a","text":"Maximizing short-term profits from timber sales."},{"id":"b","text":"Increasing the speed of tree growth through genetic modification."},{"id":"c","text":"Ensuring sustainable management and use of forest resources."},{"id":"d","text":"Eliminating all costs associated with forest management."}]'::jsonb, 'c'),
  ('fp-g00604', 'forest-production', 'forest-economics-finance', 'Easy', 'mock',
